const d=[{id:"M01",title:"Ryan und Deci · 2000 · Selbstbestimmungstheorie",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"Motivation kann auf Werten beruhen, die du selbst bejahst, auch ohne Freude an der Aufgabe. Die Theorie nennt Autonomie, Kompetenz und soziale Eingebundenheit als Grundbedürfnisse.",limitation:"Theorie und Überblick über Forschung, kein Versuch mit ODA-Fragen. Autonomie bedeutet nicht Unabhängigkeit. Belohnungen und Pflichten machen ein Ziel nicht automatisch zu einem fremden Ziel."},{id:"M02",title:"Ntoumanis und andere · 2021 · Gesundheitsprogramme, die Grundbedürfnisse unterstützen",url:"https://selfdeterminationtheory.org/wp-content/uploads/2020/05/2020_NtoumanisEtAl_MetaAnalysisHealth.pdf",type:"research",finding:"73 Studien zeigten im Durchschnitt bescheidene Vorteile für selbstbestimmte Motivation und späteres Gesundheitsverhalten. Die unmittelbare Verbesserung der körperlichen Gesundheit war statistisch nicht signifikant.",limitation:"Gesundheitsprogramme mit mehreren Bestandteilen. Die Studien unterscheiden sich stark und haben methodische Grenzen. Eine einzelne Frage zu deinen Werten ersetzt das Programm nicht. Die Ergebnisse belegen keine Wirkung für jedes Ziel."},{id:"M03",title:"Duckworth und andere · 2013 · MCII-Programm für schulische Ziele",url:"https://www.researchgate.net/publication/256294319_From_Fantasy_to_Action_Mental_Contrasting_With_Implementation_Intentions_MCII_Improves_Academic_Performance_in_Children",type:"research",finding:"Ein Versuch mit 77 Kindern der fünften Klasse umfasste drei einstündige Termine in Kleingruppen. Ergebnis, Hindernis und passende Handlung wurden wiederholt geplant. Einige schulische Ergebnisse verbesserten sich.",limitation:"Nur eine Schule. Spätere Unterschiede zwischen den Gruppen waren statistisch nicht signifikant. Unterstützung und Umfang waren auf Kinder zugeschnitten. Eine Wirkung kurzer Handyübungen für Erwachsene ist damit nicht belegt."},{id:"M04",title:"Cerasoli, Nicklin und Ford · 2014 · Motivation und Anreize",url:"https://selfdeterminationtheory.org/wp-content/uploads/2017/06/2014_Cerasoli_Intrinsic.pdf",type:"research",finding:"In 183 Stichproben hingen sowohl intrinsische Motivation als auch Anreize mit Leistung zusammen. Für Qualität und Menge der Arbeit zeigten sich unterschiedliche Muster.",limitation:"Die unterschiedlichen Befunde zeigen Zusammenhänge. Sie liefern keine allgemeingültige Anleitung für Belohnungen und zeigen nicht, dass ein gesellschaftlich anerkanntes Ziel unecht ist."},{id:"M05",title:"Lally und andere · 2010 · Modelle der Gewohnheitsbildung",url:"https://www.flexyourbrain.com/wp-content/uploads/2015/10/UL-STUDY-66-Days-IJSP_998-1009.pdf",type:"research",finding:"Bei 39 gut passenden Kurven lag der Median der modellierten Dauer bis zu 95 Prozent des Endniveaus der Automatisierung bei 66 Tagen. Eine verpasste Gelegenheit störte den modellierten Verlauf nicht wesentlich.",limitation:"Beobachtet wurde über 84 Tage. Die 254 Tage wurden darüber hinaus hochgerechnet. Das sind keine beobachteten Abschlussdaten, kein allgemeiner Zeitplan und keine Aussage über lange Unterbrechungen."},{id:"M07",title:"Wood und Rünger · 2016 · Psychologie der Gewohnheit",url:"https://dornsife.usc.edu/wendy-wood/wp-content/uploads/sites/183/2023/10/wood.runger.2016.pdf",type:"research",finding:"Wiederkehrende Situationen und wiederholte Handlungen können das Lernen von Gewohnheiten unterstützen. Bewusste Ziele und gewohnheitsmäßiges Handeln können nebeneinander bestehen.",limitation:"Überblick über Forschung, kein Versuch mit ODAs Minimum oder seiner Anleitung für Startsignale. Ein Signal garantiert keine Handlung. Kleine Handlungen müssen nicht zwangsläufig größer werden."},{id:"M08",title:"Gollwitzer und Sheeran · 2006 · Wenn-dann-Pläne",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"Konkrete Wenn-dann-Pläne verbesserten das Erreichen von Zielen im Durchschnitt über 94 unabhängige Tests. Die damalige standardisierte Effektgröße betrug d = 0,65.",limitation:"Unterschiedliche ältere Studien. Das bedeutet keine Verbesserung um 65 Prozent, keine garantierte Ausführung und keinen Vergleichswert für eine Erinnerung in einer App."},{id:"M10",title:"Wang, Wang und Gai · 2021 · Mentales Kontrastieren und Planen",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 Artikel mit 24 unabhängigen Effekten zeigten im Durchschnitt kleine bis mittlere Vorteile beim Erreichen von Zielen, wenn Ergebnis, Hindernis und passende Handlung gemeinsam geplant wurden.",limitation:"Unterschiedliche Studien und Hinweise auf Publikationsverzerrung begrenzen die Aussage zur Effektgröße. Weder erfüllte Wünsche noch ein Einfluss auf äußere Ereignisse oder jedes WOOP-Format sind damit belegt."},{id:"M13",title:"Harkin und andere · 2016 · Fortschritte verfolgen",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"Maßnahmen zum Beobachten von Fortschritten verbesserten das Erreichen von Zielen im Durchschnitt über 138 randomisierte Studien.",limitation:"Ziele und Methoden unterschieden sich. Zusammenhänge mit einzelnen Merkmalen belegen nicht, dass Aufschreiben oder Teilen die Wirkung verursacht. Eine optimale wöchentliche Häufigkeit oder die Notwendigkeit öffentlicher Angaben ist nicht belegt."},{id:"M15",title:"Fogg · Tiny Habits: Anleitung zum Planen",url:"https://tinyhabits.com/design/",type:"technique",finding:"Die Anleitung aus der Praxis verbindet eine bestehende Routine mit einer sehr kleinen Handlung. Wenn diese Verbindung nicht funktioniert, soll sie angepasst werden.",limitation:"Die Seite enthält keine kontrollierte Effektschätzung für die gesamte Anleitung. Sie belegt weder notwendiges Feiern noch eine optimale Dauer unter einer Minute oder zwangsläufiges Wachstum der Handlung."},{id:"M20",title:"NIMH · Für deine psychische Gesundheit sorgen",url:"https://www.nimh.nih.gov/health/topics/caring-for-your-mental-health",type:"guidance",finding:"Anhaltende schwere oder belastende Beschwerden, Interessenverlust oder Schwierigkeiten mit üblichen Alltagsaufgaben sprechen für fachliche Hilfe. Bei akuter Gefahr brauchst du sofort Unterstützung.",limitation:"Öffentliche Orientierung, kein Wirksamkeitstest von ODA und keine Diagnose anhand fehlender Motivation. Wenn du dir Sorgen machst, musst du weder zwei Wochen noch eine Übungsserie oder das Kursende abwarten."},{id:"motivation-sdt",title:"Ryan und Deci · 2000 · Selbstbestimmungstheorie",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"Motivation kann auf Werten beruhen, die du selbst bejahst, auch ohne Freude an der Aufgabe. Die Theorie nennt Autonomie, Kompetenz und soziale Eingebundenheit als Grundbedürfnisse.",limitation:"Theorie und Überblick über Forschung, kein Versuch mit ODA-Fragen. Autonomie bedeutet nicht Unabhängigkeit. Belohnungen und Pflichten machen ein Ziel nicht automatisch zu einem fremden Ziel."},{id:"motivation-sdt-meta",title:"Ntoumanis und andere · 2021 · Gesundheitsprogramme, die Grundbedürfnisse unterstützen",url:"https://selfdeterminationtheory.org/wp-content/uploads/2020/05/2020_NtoumanisEtAl_MetaAnalysisHealth.pdf",type:"research",finding:"73 Studien zeigten im Durchschnitt bescheidene Vorteile für selbstbestimmte Motivation und späteres Gesundheitsverhalten. Die unmittelbare Verbesserung der körperlichen Gesundheit war statistisch nicht signifikant.",limitation:"Gesundheitsprogramme mit mehreren Bestandteilen. Die Studien unterscheiden sich stark und haben methodische Grenzen. Eine einzelne Frage zu deinen Werten ersetzt das Programm nicht. Die Ergebnisse belegen keine Wirkung für jedes Ziel."},{id:"M16",title:"Fogg · Tiny Habits: Anleitung für eine positive Geste",url:"https://tinyhabits.com/rewire/",type:"technique",finding:"Fogg empfiehlt direkt nach einer kleinen Handlung eine selbst gewählte positive Geste.",limitation:"Anleitung aus der Praxis ohne kontrollierte Effektschätzung. Dass Feiern nötig ist, neuronale Verbindungen schneller entstehen oder ein Häkchen dieselbe Wirkung hat, wurde nicht unabhängig belegt."}],i=[{schemaVersion:2,revision:2,id:"motivation-1",courseId:"motivation",locale:"de",title:"Keine Lust auf die Aufgabe? Prüf dein Ziel.",goal:"Entscheide, ob dir das Ziel seinen Aufwand wert ist. Probiere dann eine Handlung, die dich ihm näherbringt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Dein Ziel kostet dich gerade viel Kraft? Schau, was dein Einsatz im Alltag verändern würde.",reason:{id:"motivation-1-reason",label:"Welche Veränderung ist dir den wöchentlichen Aufwand für dieses Ziel wert?",kind:"text",maxLength:160,optional:!0,suggestions:["Meiner Familie neue Möglichkeiten eröffnen","Meiner Neugier Zeit geben","Eine bewusst gewählte Verantwortung wahrnehmen"]},why:{id:"motivation-1-why",label:"Welche Veränderung ist dir den wöchentlichen Aufwand für dieses Ziel wert?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Eine Aufgabe kann zu deinen Werten passen, obwohl du sie ungern machst. Für ein sicheres Einkommen lernen, für die Familie sorgen oder einen Abschluss erwerben: Das können eigene Entscheidungen sein. Du kannst den Zweck bejahen, ohne die Arbeit zu mögen. Anerkennung macht Ziele nicht automatisch fremd.","Was soll das Ziel im Alltag verändern? Wie viel Zeit oder Kraft kostet es diese Woche? Entscheide: beibehalten, anpassen, verschieben oder aufgeben. Bleibst du dabei, probiere bei einer passenden Gelegenheit eine nützliche Handlung aus. Damit prüfst du eine Entscheidung. Das ist kein diagnostischer Test, der deine wahren Motive aufdeckt."],example:{title:"Leilas erste Übungsfrage",text:"Um 19 Uhr wägt Leila ihren Abschluss gegen Zeit mit der Familie ab. Sie mag den Lernstoff nicht, aber die möglichen beruflichen Chancen sind ihr wichtig. Sie bleibt dabei und beantwortet am Küchentisch eine Übungsfrage. Ihre Antwort ist unvollständig. Sie hält den Versuch fest und sucht eine neue Gelegenheit, ohne so zu tun, als hätte ihr Lernen Spaß gemacht."}},move:{invitation:"Wähle dein Ziel. Benenne erst deine eigene Handlung, bevor du ein Beispiel übernimmst.",instructions:["Passe Beispiele an: Familie versorgen, arbeiten, Beziehungen pflegen oder etwas Eigenes.","Speichere für diesen Schritt ein passendes Datum, ein Startsignal und einen Ort."],prompts:[{id:"motivation-1-0",label:"Worauf verzichtest du bewusst, wenn du dieses Ziel verfolgst?",kind:"text",maxLength:160,optional:!0}],suggestions:{action:["Beispiel: erste Übungsfrage für meinen Abschluss beantworten","Mit Maja die morgige Abholzeit klären","Einen Satz für meine Kundeninformation entwerfen","Sven die vereinbarte Frage zum Tag stellen"],minimum:["Diese Übungsfrage beantworten","Maja die vereinbarte Abholzeit schicken","Den ersten nützlichen Satz der Kundeninformation schreiben","Sven fragen, wie der heutige Termin lief"],cue:["Nachdem ich meinen Abendbrotteller abgeräumt habe","Wenn Majas Nachricht zur Abholzeit kommt","Nach meiner Arbeitspause um 14 Uhr","Wenn unser vereinbartes Abendgespräch beginnt"],place:["An meinem Küchentisch","In unserem bisherigen Chat","An meinem Computer bei der Arbeit","In unserem vereinbarten Telefonat"],minutes:[2,1,5],fallback:["Eine kürzere Frage aus diesen Notizen beantworten","Auf dem vereinbarten Weg anrufen","Den Satz in meine zugänglichen Notizen diktieren","Stattdessen unser vereinbartes Gespräch per Nachricht anbieten"],observation:["Meine Antwort und die dafür gebrauchte Zeit","Abholzeit geschickt; eine Antwort zählt gesondert","Welcher nützliche Satz jetzt in der Kundeninformation steht","Frage gestellt, auch wenn keine Antwort kam"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],bundles:[{action:"Beispiel: erste Übungsfrage für meinen Abschluss beantworten",minimum:"Diese Übungsfrage beantworten",cue:"Nachdem ich meinen Abendbrotteller abgeräumt habe",place:"An meinem Küchentisch",fallback:"Eine kürzere Frage aus diesen Notizen beantworten",observation:"Meine Antwort und die dafür gebrauchte Zeit",minutes:2},{action:"Mit Maja die morgige Abholzeit klären",minimum:"Maja die vereinbarte Abholzeit schicken",cue:"Wenn Majas Nachricht zur Abholzeit kommt",place:"In unserem bisherigen Chat",fallback:"Auf dem vereinbarten Weg anrufen",observation:"Abholzeit geschickt; eine Antwort zählt gesondert",minutes:1},{action:"Einen Satz für meine Kundeninformation entwerfen",minimum:"Den ersten nützlichen Satz der Kundeninformation schreiben",cue:"Nach meiner Arbeitspause um 14 Uhr",place:"An meinem Computer bei der Arbeit",fallback:"Den Satz in meine zugänglichen Notizen diktieren",observation:"Welcher nützliche Satz jetzt in der Kundeninformation steht",minutes:5},{action:"Sven die vereinbarte Frage zum Tag stellen",minimum:"Sven fragen, wie der heutige Termin lief",cue:"Wenn unser vereinbartes Abendgespräch beginnt",place:"In unserem vereinbarten Telefonat",fallback:"Stattdessen unser vereinbartes Gespräch per Nachricht anbieten",observation:"Frage gestellt, auch wenn keine Antwort kam",minutes:2}]},suggested:{action:"Beispiel: erste Übungsfrage für meinen Abschluss beantworten",minimum:"Diese Übungsfrage beantworten",minutes:2,cueHint:"Nachdem ich meinen Abendbrotteller abgeräumt habe",placeHint:"An meinem Küchentisch",obstacleHint:"Beispiel: Die heutige Frage konkurriert mit Zeit für meine Familie",fallbackHint:"Eine kürzere Frage aus diesen Notizen beantworten",observationHint:"Meine Antwort und die dafür gebrauchte Zeit"},stopRule:"Dräng dich bei Krankheit, Gefahr oder anhaltenden Schwierigkeiten im Alltag nicht zum Weitermachen. Unterstützung gibt es schon jetzt.",accessibleAlternative:"Nutze Audio, Diktieren, Hilfsmittel oder vereinbarte Hilfe. Du kannst auch ausdrücklich pausieren."},result:{question:"Hast du die Handlung ausprobiert, die du gewählt hast?",observationPrompt:"Was hast du getan? Was hat es dich gekostet?"},judgment:{primary:{id:"motivation-1-decision",scenario:"Leila lernt ungern für einen Abschluss. Sie möchte verlässlichere berufliche Chancen für ihre Familie. Auch ihre Kolleginnen und Kollegen finden den Abschluss wertvoll.",question:"Wie prüft sie am besten, ob sie dabei bleiben will?",options:[{id:"motivation-1-endorse",text:"Prüfen, ob sie Nutzen und Zeitaufwand selbst bejaht. Dann eine Übungsfrage beantworten.",feedback:"So trennt sie fehlende Lust von ihrer eigenen Entscheidung und probiert eine machbare Handlung. Anerkennung und ein eigener Grund können zusammenpassen. Passt der Aufwand nicht, darf sie das Ziel weiter anpassen oder verschieben."},{id:"motivation-1-interest",text:"Eine Woche lang ein angenehmeres Ziel ausprobieren, bevor sie entscheidet, ob dieser Abschluss noch ihr eigenes Ziel ist.",feedback:"Ein anderes Interesse zu erkunden kann helfen. Freude allein entscheidet aber nicht, ob dieser Abschluss ihr eigenes Ziel ist. Erst zählen der selbst gewählte Nutzen und der Aufwand. Auch wertvolle Aufgaben können unangenehm bleiben."},{id:"motivation-1-advice",text:"Kollegen mit Abschluss fragen, welche Qualifikation sie wählen würden. Dann deren Empfehlung zum eigenen Ziel machen.",feedback:"Kollegen können Möglichkeiten und Anforderungen erklären. Sie können Leila aber nicht abnehmen, ihren Einsatz abzuwägen. Bevor sie deren Ziel übernimmt, braucht sie einen eigenen Grund und Zeit, die in ihrem Alltag tatsächlich verfügbar ist."}],bestOptionId:"motivation-1-endorse"}},carry:{takeaway:"Auch ein eigenes Ziel kann schwerfallen. Prüfe Nutzen und Aufwand. Probiere dann eine passende Handlung aus.",followUp:{questionId:"motivation-1-return",question:"Hat der Versuch deinem gewählten Zweck gedient? Ist dir die Sache den Aufwand weiter wert?",observationPrompt:"Was hast du getan? Was hat es dich gekostet?",adjustmentPrompt:"Welche einzelne Änderung hilft deinem nächsten Versuch im Alltag?"}},goDeeper:{sections:[{heading:"Ein eigenes Ziel muss keinen Spaß machen",paragraphs:["Ryan und Decis Selbstbestimmungstheorie unterscheidet Freude an einer Tätigkeit von Gründen, die du selbst bejahst. Auch ein von außen angeregtes Ziel kann dir wichtig werden: ein Abschluss, Einkommen, Fürsorge oder eine gemeinsame Verantwortung. Die Tätigkeit darf dabei langweilig sein. Autonomie heißt, eine Wahl zu erleben. Sie bedeutet nicht, frei von allen Pflichten und Einflüssen zu sein. Ihr Text von 2000 stellt eine Theorie und Forschung vor. Er ist kein Versuch mit dieser Lektion. [M01]","Beibehalten, anpassen, verschieben oder aufgeben: Diese Entscheidung ist eine Reflexionsübung von ODA. Sie deckt keine reinen Motive auf und bescheinigt keinem Ziel Echtheit. Cerasoli und sein Team fanden in einer großen Metaanalyse: Intrinsische Motivation und Anreize können beide mit Leistung zusammenhängen. Die Muster unterschieden sich je nach Qualität und Menge der Arbeit. Belohnungen sind damit nicht pauschal gut oder schlecht. [M04] Du kannst mehrere Beweggründe anerkennen und trotzdem entscheiden, ob die Handlung dem Leben dient, das du führen möchtest."]},{heading:"Eine Wertefrage ersetzt kein ganzes Programm",paragraphs:["Ntoumanis und sein Team fassten 73 Studien zu Gesundheitsprogrammen zusammen, die auf der Selbstbestimmungstheorie aufbauten. Im Durchschnitt fanden sie bescheidene Vorteile für selbstbestimmte Motivation und späteres Gesundheitsverhalten. Die Programme boten mehrere Formen von Unterstützung. Die Ergebnisse unterschieden sich deutlich. Die unmittelbare Verbesserung körperlicher Gesundheit war statistisch nicht signifikant. Damit ist derselbe Nutzen für jedes berufliche, schulische oder persönliche Ziel nicht belegt. [M02]","Eine einzelne Frage nach deinem Grund kann solche Programme nicht ersetzen. Hier hilft dein Grund bei einem praktischen Versuch: ein Ziel, eine tatsächlich ausgeführte Handlung, eine ehrliche Notiz und eine nächste Gelegenheit. Schau beim ersten Versuch auf Machbarkeit, Zugang und Aufwand. Du musst keine Begeisterung empfinden. Behalte Einzelheiten für dich, wenn du möchtest. Die nächsten Lektionen bleiben bei derselben Richtung. Du prüfst ein sinnvolles Minimum, ein brauchbares Startsignal und eine passende Handlung bei einem echten Hindernis. Brauchen dein Ziel oder deine Umstände Aufmerksamkeit, darfst du ausdrücklich pausieren oder um Unterstützung bitten."]}],sourceIds:["M01","M04","M02"]}},{schemaVersion:2,revision:2,id:"motivation-2",courseId:"motivation",locale:"de",title:"Buch wieder geöffnet, aber nichts gelesen?",goal:"Probiere deine bisherige Handlung so klein aus, dass sie trotzdem etwas Nützliches ergibt.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Buch auf, aber nichts gelesen? Mach den nützlichen Teil so klein, dass du ihn tun kannst.",reason:{id:"motivation-2-useful-unit-cost",label:"Welche Vorbereitung könntest du beenden, damit du zum nützlichen Teil kommst?",kind:"text",maxLength:160,optional:!0,suggestions:["Nicht wieder öffnen, einen Satz lesen","Nicht umsortieren, einen Satz schreiben","Weniger tun, den nützlichen Teil behalten"]},why:{id:"motivation-2-why",label:"Welches nützliche Minimum würde deinem gewählten Zweck dienen?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bleib bei dem Ziel, das du gewählt hast. Verkleinere die Handlung, bis sie in deinen heutigen Tag passt. Der nützliche Teil soll bleiben. Leg das Buch griffbereit hin und lies dann einen Satz. Öffne die Bewerbung und schreibe einen brauchbaren Satz. Das Bereitlegen ist Vorbereitung. Der Satz gehört zur Handlung, die du ausprobieren willst.","Gewohnheitsforschung beschreibt wiederholte Handlungen in wiederkehrenden Situationen. Sie zeigt nicht, dass jeder winzige Anfang wächst oder ein Häkchen genauso wirkt wie Feiern. Dein Minimum darf klein bleiben. Probiere es einmal aus. Halte fest, was tatsächlich passiert ist. Prüfe später, ob dieser Umfang deinem gewählten Zweck noch dient."],example:{title:"Leilas kürzere Frage",text:"Am Dienstag hat Leila nach dem Abendessen zwei Minuten für denselben Abschluss. Sie legt ihre Notizen griffbereit hin und beantwortet eine kurze Übungsfrage. Dann hört sie auf. Zeit mit der Familie ist ihr auch wichtig. Ihre Antwort braucht Korrekturen. Sie hält die Antwort als Arbeit und das Bereitlegen als Vorbereitung fest. Sie verlängert die Lernzeit nicht."}},move:{invitation:"Bleib bei deiner gespeicherten Handlung. Verkleinere den nützlichen Teil, bevor du speicherst.",instructions:["Behalte Handlung und passenden Ort bei. Ändere nur dein nützliches Minimum.","Leg die nötigen Dinge griffbereit hin. Führe dann dieses Minimum aus."],prompts:[],suggestions:{action:["Beispiel: nächste Übungsfrage für meinen Abschluss beantworten","Meinen gespeicherten Bewerbungsabsatz schreiben","Meinen vereinbarten Teil des Küchenputzens erledigen"],minimum:["Den ersten Teil dieser Frage beantworten","Einen brauchbaren Satz für diesen Absatz schreiben","Die beiden vereinbarten Tassen abwaschen"],cue:["Nachdem ich meinen Abendbrotteller abgeräumt habe","Nach meiner Arbeitspause um 14 Uhr","Nachdem unser gemeinsames Essen vorbei ist"],place:["An meinem Küchentisch","An meinem Computer bei der Arbeit","An meiner für mich zugänglichen Küchenspüle"],minutes:[2,1],fallback:["Den ersten Teil anhand zugänglicher Notizen diktieren","Einen brauchbaren Satz in meine Notizen diktieren","Eine andere vereinbarte, für mich machbare Putzaufgabe wählen"],observation:["Frage beantwortet oder nur Material bereitgelegt","Satz geschrieben oder nur Datei geöffnet","Aufgabe erledigt oder nur Putzzeug hingestellt"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],bundles:[{action:"Beispiel: nächste Übungsfrage für meinen Abschluss beantworten",minimum:"Den ersten Teil dieser Frage beantworten",cue:"Nachdem ich meinen Abendbrotteller abgeräumt habe",place:"An meinem Küchentisch",fallback:"Den ersten Teil anhand zugänglicher Notizen diktieren",observation:"Frage beantwortet oder nur Material bereitgelegt",minutes:2},{action:"Meinen gespeicherten Bewerbungsabsatz schreiben",minimum:"Einen brauchbaren Satz für diesen Absatz schreiben",cue:"Nach meiner Arbeitspause um 14 Uhr",place:"An meinem Computer bei der Arbeit",fallback:"Einen brauchbaren Satz in meine Notizen diktieren",observation:"Satz geschrieben oder nur Datei geöffnet",minutes:1},{action:"Meinen vereinbarten Teil des Küchenputzens erledigen",minimum:"Die beiden vereinbarten Tassen abwaschen",cue:"Nachdem unser gemeinsames Essen vorbei ist",place:"An meiner für mich zugänglichen Küchenspüle",fallback:"Eine andere vereinbarte, für mich machbare Putzaufgabe wählen",observation:"Aufgabe erledigt oder nur Putzzeug hingestellt",minutes:2}]},suggested:{action:"Beispiel: nächste Übungsfrage für meinen Abschluss beantworten",minimum:"Den ersten Teil dieser Frage beantworten",minutes:2,cueHint:"Nachdem ich meinen Abendbrotteller abgeräumt habe",placeHint:"An meinem Küchentisch",obstacleHint:"Beispiel: Ich lege die Materialien bereit, beantworte aber nichts",fallbackHint:"Den ersten Teil anhand zugänglicher Notizen diktieren",observationHint:"Frage beantwortet oder nur Material bereitgelegt"},stopRule:"Wähle eine sichere Handlung. Hör bei Schmerzen, Krankheit, dringenden Bedürfnissen oder einer für dich unzugänglichen Umgebung auf.",accessibleAlternative:"Höre zu, diktiere oder nutze Hilfsmittel. Wähle bei Bedarf ausdrücklich Vorbereitung und eine spätere Gelegenheit zum Anwenden."},result:{question:"Hast du den nützlichen Teil deines Minimums tatsächlich getan?",observationPrompt:"Was war die eigentliche Handlung, und was war nur Vorbereitung?"},judgment:{primary:{id:"motivation-2-decision",scenario:"Du möchtest eine Bewerbung schreiben. In drei Sitzungen hast du die Datei geöffnet, aber nichts geschrieben. Du hast zwei Minuten und weißt, was in den geforderten Abschnitt gehört.",question:"Welches Minimum prüft jetzt, ob du sinnvoll weiterkommst?",options:[{id:"motivation-2-bigger",text:"Später mehr Zeit reservieren, damit es sich lohnt, mit einer vollständigen Antwort anzufangen.",feedback:"Mehr Zeit kann beim Fertigstellen helfen. Aber damit prüfst du nicht, warum es bisher bei Vorbereitung bleibt. Schreibe jetzt einen ersten Satz. Danach kannst du entscheiden, ob du mehr Zeit brauchst."},{id:"motivation-2-outline",text:"In den zwei Minuten drei Stichpunkte skizzieren. Den geforderten Abschnitt dann in einem längeren Zeitfenster schreiben.",feedback:"Stichpunkte können den Inhalt klären. Du weißt aber schon, was in diesen Abschnitt gehört. Bisher scheitert der Anfang des Textes. Ein erster Satz prüft dieses Hindernis jetzt. Eine Skizze hältst du als Vorbereitung fest."},{id:"motivation-2-sentence",text:"Einen ersten Satz für den geforderten Abschnitt schreiben. Aufhören, wenn die verfügbare Zeit vorbei ist.",feedback:"So tust du die eigentliche Handlung und hast etwas zum Überarbeiten. Das garantiert keinen Bewerbungserfolg und verlangt keine längere Sitzung. Halte den geschriebenen Satz getrennt vom Öffnen der Datei fest."}],bestOptionId:"motivation-2-sentence"}},carry:{takeaway:"Mach den Anfang möglich. Verkleinere die Handlung, aber behalte ihren nützlichen Teil.",followUp:{questionId:"motivation-2-return",question:"Hat deine kleine Version eine nützliche Handlung ergeben, oder hast du nur alles vorbereitet?",observationPrompt:"Was war die eigentliche Handlung, und was war nur Vorbereitung?",adjustmentPrompt:"Welche einzelne Änderung hilft deinem nächsten Versuch im Alltag?"}},goDeeper:{sections:[{heading:"Klein ist eine bewusste Wahl, keine Garantie",paragraphs:["Wood und Rünger beschreiben Gewohnheiten als gelernte Handlungen, die mit wiederkehrenden Situationen verbunden sind. Wiederholung kann dabei helfen, dass etwas automatischer abläuft. Bewusste Ziele können trotzdem wichtig bleiben. Ihr Überblick belegt weder, dass ein Satz der optimale Umfang ist, noch dass jede kleine Handlung zwangsläufig wächst. Hier wählst du einen kleinen Teil aus. Du prüfst, ob du ihn in deiner tatsächlichen Woche ausführen kannst und ob er dir etwas bringt. [M07]","Trenne anhand dieses kleinen Teils die Vorbereitung von der Handlung, die du üben willst. Eine beantwortete Frage kannst du prüfen. Ein gelesener Satz kann dir Informationen geben. Einen geschriebenen Satz kannst du bearbeiten. Materialien bereitzulegen hilft bei der Vorbereitung, ersetzt aber diese Handlungen nicht. Dienen mehrere kleine Versuche deinem gewählten Zweck nie, schau noch einmal auf Handlung oder Ziel. Vielleicht brauchst du einen anderen Teil, mehr Unterstützung oder einen längeren verfügbaren Zeitraum. Ein leicht gesetztes Häkchen ist kein Grund, Fortschritt zu erfinden. [M07]"]},{heading:"Auch die Anleitung aus der Praxis hat Grenzen",paragraphs:["BJ Foggs Tiny-Habits-Anleitung verbindet eine bestehende Routine mit einer sehr kleinen Handlung. Funktioniert die Verbindung nicht, empfiehlt er eine Änderung. Das ist eine Methode aus der Praxis. Die geprüfte Seite belegt nicht unabhängig, dass die gesamte Anleitung besser wirkt als ein gewöhnlicher Plan mit Startsignal. Sie zeigt auch nicht, dass jede Handlung weniger als eine Minute dauern muss. [M15]","Fogg empfiehlt außerdem direkt danach eine selbst gewählte positive Geste. Ob dadurch neuronale Verbindungen schneller entstehen, Feiern nötig ist oder ein Häkchen dieselbe verstärkende Wirkung hat, wurde im Dossier nicht durch kontrollierte Forschung belegt. [M16] Wenn du zufrieden bist, darfst du das wahrnehmen. Erzwingen musst du es nicht. Eine ehrliche Notiz beschreibt, was passiert ist. Wie du dich danach gefühlt hast, ist eine eigene Information. Du darfst beim nützlichen Minimum aufhören, morgen dieselbe Größe beibehalten und Hilfsmittel oder Zugang anpassen. Weniger zu tun sagt nichts Schlechtes über deinen Charakter aus."]}],sourceIds:["M07","M15","M16"]}},{schemaVersion:2,revision:2,id:"motivation-3",courseId:"motivation",locale:"de",title:"Erinnerung gehört. Trotzdem nicht angefangen.",goal:"Teste dein bisheriges Minimum bei einem Startsignal: Sind Zeit, Materialien und Zugang verfügbar?",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Deine Erinnerung klingelt noch im Bus? Wähle ein Startsignal, bei dem du die Handlung tatsächlich ausführen kannst.",reason:{id:"motivation-3-available-setting-cost",label:"Welchen verfügbaren Ort nutzt du? Was verschiebst du, um diese Gelegenheit freizuhalten?",kind:"text",maxLength:160,optional:!0,suggestions:["Meine feste Pause freihalten und nutzen","Eine verschiebbare Hausarbeit anders einplanen","Beim Üben die Betreuung sicherstellen"]},why:{id:"motivation-3-why",label:"Bei welcher echten Gelegenheit hast du Zeit für dein gewähltes Ziel?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Dein Startsignal muss drei Bedingungen erfüllen: Es tritt ein, du bemerkst es und du kannst dann handeln. Nachdem du dein Kind zur Schule gebracht hast, geht Schreibtischarbeit nicht, wenn du direkt zur Arbeit fährst. Behalte dein nützliches Minimum. Wähle eine Umgebung, in der es möglich ist.","Konkrete Wenn-dann-Pläne können dir helfen, Absichten umzusetzen. Wiederholung in derselben Situation kann eine Gewohnheit unterstützen. Es gibt kein Abschlussdatum für alle. Heute prüfst du dein Startsignal. Du musst nicht schon automatisch handeln. Notiere, welche der drei Bedingungen erfüllt waren und was du ändern musst."],example:{title:"Leila findet eine passende Gelegenheit",text:"Leila wollte ihre Frage beantworten, nachdem sie ihr Kind zur Schule gebracht hatte. Sie fuhr aber ohne Notizen direkt zur Arbeit. Am Mittwoch nimmt sie sich dieselbe Frage nach dem Abendessen am Küchentisch vor. Das Startsignal kommt, und sie bemerkt es. Sie antwortet vor dem Abräumen. Eine Antwort ist nützlich. Auch die frühere, ungeeignete Zeit bleibt in ihren Notizen stehen."}},move:{invitation:"Bleib beim gespeicherten Schritt. Wähle ein Ereignis und einen Ort, die ihn ermöglichen.",instructions:["Prüfe: Tritt das Startsignal ein, bemerkst du es und kannst du deine Handlung dann ausführen?","Wähle das Datum. Prüfe, ob Materialien und Zugang dann vorhanden sind."],prompts:[],suggestions:{action:["Beispiel: meine gespeicherte Übungsfrage zum Abschluss beantworten","Meinen gespeicherten Bewerbungssatz schreiben","Meinen vereinbarten Teil des Küchenputzens erledigen"],minimum:["Dieselbe Übungsfrage beantworten","Denselben nützlichen Satz schreiben","Dieselben beiden vereinbarten Tassen abwaschen"],cue:["Nachdem ich meinen Abendbrotteller abgeräumt habe","Wenn meine feste Pause um 12:30 beginnt","Nachdem unser gemeinsames Essen vorbei ist"],place:["An meinem Küchentisch","An meinem für mich zugänglichen Pausentisch","An meiner für mich zugänglichen Küchenspüle"],minutes:[2,1],fallback:["Beim morgigen Essen meine zugänglichen Notizen nutzen","Den Satz anhand meiner gespeicherten Notizen diktieren","Den nächsten vereinbarten Putztermin mit gesicherter Betreuung nutzen"],observation:["Startsignal da, bemerkt und Handlung möglich","War derselbe Schritt in dieser Umgebung möglich","Startsignal da und vereinbarte Aufgabe möglich"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],bundles:[{action:"Beispiel: meine gespeicherte Übungsfrage zum Abschluss beantworten",minimum:"Dieselbe Übungsfrage beantworten",cue:"Nachdem ich meinen Abendbrotteller abgeräumt habe",place:"An meinem Küchentisch",fallback:"Beim morgigen Essen meine zugänglichen Notizen nutzen",observation:"Startsignal da, bemerkt und Handlung möglich",minutes:2},{action:"Meinen gespeicherten Bewerbungssatz schreiben",minimum:"Denselben nützlichen Satz schreiben",cue:"Wenn meine feste Pause um 12:30 beginnt",place:"An meinem für mich zugänglichen Pausentisch",fallback:"Den Satz anhand meiner gespeicherten Notizen diktieren",observation:"War derselbe Schritt in dieser Umgebung möglich",minutes:1},{action:"Meinen vereinbarten Teil des Küchenputzens erledigen",minimum:"Dieselben beiden vereinbarten Tassen abwaschen",cue:"Nachdem unser gemeinsames Essen vorbei ist",place:"An meiner für mich zugänglichen Küchenspüle",fallback:"Den nächsten vereinbarten Putztermin mit gesicherter Betreuung nutzen",observation:"Startsignal da und vereinbarte Aufgabe möglich",minutes:2}]},suggested:{action:"Beispiel: meine gespeicherte Übungsfrage zum Abschluss beantworten",minimum:"Dieselbe Übungsfrage beantworten",minutes:2,cueHint:"Nachdem ich meinen Abendbrotteller abgeräumt habe",placeHint:"An meinem Küchentisch",obstacleHint:"Beispiel: Bei meinem bisherigen Startsignal hatte ich keine Notizen dabei",fallbackHint:"Beim morgigen Essen meine zugänglichen Notizen nutzen",observationHint:"Startsignal da, bemerkt und Handlung möglich"},stopRule:"Übe nicht beim Autofahren oder dort, wo du Versorgung, Betreuung oder Sicherheit beeinträchtigst.",accessibleAlternative:"Nutze eine sichtbare oder zugängliche Erinnerung, Audiomaterial, vereinbarte Hilfe oder ein späteres, passendes Startsignal."},result:{question:"Konntest du beim Startsignal dein Minimum tatsächlich ausführen?",observationPrompt:"Kam das Startsignal, hast du es bemerkt und konntest du dann handeln?"},judgment:{primary:{id:"motivation-3-usable-setting-decision",scenario:"Leila will ihre gespeicherte Frage heute beantworten. Nachdem sie ihr Kind zur Schule gebracht hat, beginnt sofort die Arbeit. Beim Abendessen hat sie sicher fünf Minuten und ihre Notizen. In der festen Mittagspause könnte sie eine Handykopie nutzen. Morgen wäre Lernen im Zug möglich, aber die Abfahrt ist unbestätigt.",question:"Wie probiert sie heute denselben Schritt am besten aus?",options:[{id:"motivation-3-dinner",text:"Die sichere Zeit beim Abendessen mit vorhandenen Notizen nutzen und dieselbe gespeicherte Frage beantworten.",feedback:"So verändert sie die ungeeignete Gelegenheit und behält Aufgabe und Materialien bei. Die Zeit ist heute sicher verfügbar. Halte fest, ob das Signal kommt, bemerkt wird und die Antwort dann tatsächlich möglich ist."},{id:"motivation-3-phone-copy",text:"Mittags eine Handykopie anfertigen. Die Frage dann in einer späteren verfügbaren Pause beantworten.",feedback:"Mobile Notizen könnten bei künftigen Arbeitspausen helfen. Diese Wahl nutzt die heutige sichere Gelegenheit aber nur für Vorbereitung. Die Antwort bleibt ohne Datum. Beim Abendessen kann sie die Handlung heute mit vorhandenen Materialien ausprobieren."},{id:"motivation-3-train",text:"Die Notizen für den morgigen Zug einpacken. Dieselbe Frage beantworten, sobald seine Abfahrt bestätigt ist.",feedback:"Der Zug könnte nach der Bestätigung passen. Diese Wahl verschiebt den Versuch trotz einer verfügbaren Zeit heute. Passt das Abendessen doch nicht mehr, sollte Leila das Zugdatum bestätigen, bevor sie dafür einen Plan festlegt."}],bestOptionId:"motivation-3-dinner"}},carry:{takeaway:"Ein brauchbares Startsignal tritt ein, wird bemerkt und lässt dich die Handlung ausführen.",followUp:{questionId:"motivation-3-return",question:"Welche Bedingung fehlte: Startsignal ausgeblieben, übersehen oder Handlung nicht möglich?",observationPrompt:"Kam das Startsignal, hast du es bemerkt und konntest du dann handeln?",adjustmentPrompt:"Welche einzelne Änderung hilft deinem nächsten Versuch im Alltag?"}},goDeeper:{sections:[{heading:"Ein Startsignal kannst du prüfen",paragraphs:["Gollwitzer und Sheerans Überblick von 2006 fasste 94 unabhängige Tests von Plänen zusammen, die eine Situation mit einer gewählten Handlung verbinden. Im Durchschnitt wurden Ziele besser erreicht. Die damalige standardisierte Effektgröße von 0,65 bedeutet keine Verbesserung um 65 Prozent. Sie sagt auch nicht voraus, wie deine App-Erinnerung wirkt. Die historischen Durchschnittswerte stammen aus unterschiedlichen Zielen und Umgebungen. Dieses konkrete Startsignal beim Lernen wurde damit nicht geprüft. [M08]","Wood und Rünger beschreiben Wiederholung in derselben Umgebung als Teil des Lernens von Gewohnheiten. Ein Signal allein garantiert keine Handlung. Nicht jede Routine läuft automatisch ab. [M07] ODAs Prüfung „eingetreten, bemerkt, möglich“ ist eine Lernhilfe. Damit unterscheidest du eine übersehene Erinnerung von fehlenden Materialien oder einer anderen Pflicht. Kam das Startsignal nicht, halte gegebenenfalls fest, dass es keine Gelegenheit gab. Kam es, ohne dass du gehandelt hast, kannst du auch das ehrlich festhalten. Daraus muss kein Urteil über deine Entschlossenheit werden."]},{heading:"66 Tage waren eine Modellschätzung",paragraphs:["Lallys Studie von 2010 beobachtete gewählte tägliche Handlungen über 84 Tage. Bei 39 Personen passten die Kurven der Automatisierung gut zu den Daten. Der Median der modellierten Dauer bis zu 95 Prozent des Endniveaus lag bei 66 Tagen. Die Schätzungen reichten von 18 bis 254 Tagen. Die längste lag außerhalb der Beobachtungszeit. Das waren keine beobachteten schnellsten, durchschnittlichen und langsamsten Abschlussdaten für Gewohnheiten. [M05]","Deine Arbeit für einen Abschluss entspricht nicht den Ess-, Trink- oder Bewegungsaufgaben der Studie. Nutze deren Schätzung nicht als Frist oder Beweis, dass Lernen mühelos werden müsste. Bleib bei demselben Versuch. Schau auf verfügbare Gelegenheiten, nützliche Handlungen und die Bedingungen, die geholfen haben. Ein Startsignal kann an Werktagen passen, während Schichtarbeit oder Betreuung eine andere Lösung brauchen. Probiere bewusst eine Änderung aus. Behalte die früheren Notizen bei. So vergleichst du beim Rückblick die tatsächlichen Umstände und keine erfundene Routine."]}],sourceIds:["M08","M07","M05"]}},{schemaVersion:2,revision:2,id:"motivation-4",courseId:"motivation",locale:"de",title:"Plane für den Moment, an dem es hakt",goal:"Teste bei einem beobachteten Hindernis eine machbare Handlung. Schütze echte Bedürfnisse und Verantwortlichkeiten.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Lernzeit genau beim Zubettbringen? Gut zureden ersetzt niemanden, der die Kinderbetreuung übernimmt.",reason:{id:"motivation-4-accepted-change-cost",label:"Welche konkrete Änderung akzeptierst du, um das Hindernis aus deinen Notizen anzugehen?",kind:"text",maxLength:160,optional:!0,suggestions:["Zeit verschieben, nützlichen Schritt beibehalten","Gezielt fragen, statt Betreuung vorauszusetzen","Zugang ändern, statt mehr Anstrengung verlangen"]},why:{id:"motivation-4-why",label:"Was muss geschützt bleiben, während du an diesem Ziel arbeitest?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Behalte dein Ziel und deinen nützlichen Schritt. Prüfe einen echten Versuch. Wähle ein Hindernis: Abschweifen, fehlende Materialien, Betreuung oder ein gesundheitliches Bedürfnis. Ergebnis, Hindernis und passende Handlung gemeinsam zu planen zeigt in Studien durchschnittlich bescheidene Vorteile. Fehlende Zeit oder Hilfe zaubert es nicht herbei.","Wähle eine passende Handlung. Bei Ablenkung kann eine andere Umgebung helfen. Betreuung braucht gesicherte Zeit oder vereinbarte Hilfe. Bei Krankheit kann Erholung nötig sein. Plane den ersten nützlichen Schritt, den deine Lösung ermöglicht. Probiere ihn bei der nächsten passenden Gelegenheit. Proben ist Vorbereitung, kein Beleg, dass der Ersatzplan funktioniert."],example:{title:"Leilas gesicherte Lernzeit",text:"Am Donnerstag kommt Leilas Startsignal beim Zubettbringen ihres Kindes. Ihr Partner übernimmt danach vereinbarungsgemäß fünf Minuten die Betreuung. Leila verschiebt dieselbe Frage auf diese Zeit. Sie beantwortet sie am Tisch, während die Betreuung gesichert bleibt. Sie hält die Vereinbarung und die Antwort fest. Die Frage braucht noch Arbeit. Betreuung für morgen setzt sie nicht voraus."}},move:{invitation:"Passe eine Bedingung an dein beobachtetes Hindernis an. Behalte deine nützliche Handlung.",instructions:["Betreuung vereinbart? Probiere denselben Schritt. Ändere nur, was dich dabei hinderte.","Ohne Vereinbarung: Wähle „Diesen Schritt anpassen“, „Unterstützung“. Bitte jemanden um eine Aufgabe zur konkreten Zeit.","Bei Absage nutze verfügbare Zeit oder pausiere. Unterstützung und Übung bleiben getrennt."],prompts:[{id:"motivation-4-support-request",label:"Wen bittest du um welche Hilfe, wann?",kind:"text",maxLength:160,optional:!0,visible:!0,help:"Beispiel: Maja per Nachricht um fünf Minuten Kinderbetreuung bitten."}],suggestions:{action:["Beispiel: meinen gespeicherten Bewerbungssatz schreiben","Meine Frage während der vereinbarten Betreuung beantworten","Meinen geplanten Abschnitt als Audio anhören"],minimum:["Denselben nützlichen Bewerbungssatz schreiben","Dieselbe Übungsfrage beantworten","Denselben nützlichen Abschnitt anhören"],cue:["Nach meiner Arbeitspause um 14 Uhr","Wenn die vereinbarten fünf Minuten Betreuung beginnen","Wenn meine bestätigte Pause um 12:30 beginnt"],place:["An meinem Computer bei der Arbeit","An meinem Küchentisch","An meinem ruhigen, für mich zugänglichen Pausenplatz"],minutes:[2,5],fallback:["Unnötige Meldungen stummschalten; für Dringendes erreichbar bleiben","Fällt die Betreuung aus, die Übung pausieren","Bei Audioausfall eine zugängliche Fassung anfordern"],observation:["Meldungen aufgetaucht; hat meine Reaktion Schreiben ermöglicht","Betreuung gesichert und Frage beantwortet gesondert festhalten","Zugang vorhanden und Abschnitt gehört gesondert festhalten"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],bundles:[{action:"Beispiel: meinen gespeicherten Bewerbungssatz schreiben",minimum:"Denselben nützlichen Bewerbungssatz schreiben",cue:"Nach meiner Arbeitspause um 14 Uhr",place:"An meinem Computer bei der Arbeit",fallback:"Unnötige Meldungen stummschalten; für Dringendes erreichbar bleiben",observation:"Meldungen aufgetaucht; hat meine Reaktion Schreiben ermöglicht",minutes:2},{action:"Meine Frage während der vereinbarten Betreuung beantworten",minimum:"Dieselbe Übungsfrage beantworten",cue:"Wenn die vereinbarten fünf Minuten Betreuung beginnen",place:"An meinem Küchentisch",fallback:"Fällt die Betreuung aus, die Übung pausieren",observation:"Betreuung gesichert und Frage beantwortet gesondert festhalten",minutes:2},{action:"Meinen geplanten Abschnitt als Audio anhören",minimum:"Denselben nützlichen Abschnitt anhören",cue:"Wenn meine bestätigte Pause um 12:30 beginnt",place:"An meinem ruhigen, für mich zugänglichen Pausenplatz",fallback:"Bei Audioausfall eine zugängliche Fassung anfordern",observation:"Zugang vorhanden und Abschnitt gehört gesondert festhalten",minutes:5}]},suggested:{action:"Beispiel: meinen gespeicherten Bewerbungssatz schreiben",minimum:"Denselben nützlichen Bewerbungssatz schreiben",minutes:2,cueHint:"Nach meiner Arbeitspause um 14 Uhr",placeHint:"An meinem Computer bei der Arbeit",obstacleHint:"Beispiel: Unnötige Handymeldungen haben meinen letzten Satz unterbrochen",fallbackHint:"Unnötige Meldungen stummschalten; für Dringendes erreichbar bleiben",observationHint:"Meldungen aufgetaucht; hat meine Reaktion Schreiben ermöglicht"},stopRule:"Sichere Betreuung und dringende Bedürfnisse ab. Wähle bei Krankheit oder unsicheren Umständen Unterstützung oder Erholung.",accessibleAlternative:"Vereinbare Hilfe, ändere Zugang oder Zeitpunkt. Du kannst Unterstützung oder Erholung wählen."},result:{question:"Konntest du dein Minimum damit ausführen?",observationPrompt:"Trat das Hindernis auf, und was hast du daraufhin getan?"},judgment:{primary:{id:"motivation-4-covered-slot-decision",scenario:"Gitarreüben kollidiert mit dem Zubettbringen. Für heute Abend sind fünf Minuten Betreuung bestätigt. Die Gitarre ist bereit. Eine Nachbarin könnte am Samstag länger helfen, hat aber noch nicht zugesagt. Der Elternteil will heute eine kurze Tonfolge spielen, ohne die Betreuung zu gefährden.",question:"Welche Lösung passt am besten zum nächsten Versuch?",options:[{id:"motivation-4-confirmed-cover",text:"Die kurze Tonfolge während der bestätigten fünf Minuten heute spielen. Aufhören, sobald die vereinbarte Betreuung endet.",feedback:"Die Vereinbarung schafft die fehlende Bedingung, ohne die Aufgabe zu vergrößern. Spiele dieselbe Tonfolge. Halte Üben und Betreuung gesondert fest. Die heutige Vereinbarung bedeutet nicht, dass Hilfe für spätere Tage schon gebucht ist."},{id:"motivation-4-saturday-request",text:"Die Nachbarin nach längerer Betreuung am Samstag fragen. Erst nach ihrer Zusage diese Übungszeit planen.",feedback:"Das ist eine sichere Bitte um Unterstützung für später. Sie prüft aber nicht die kurze Tonfolge, die heute schon möglich ist. Wähle sie, wenn heute nicht mehr passt. Samstag bleibt bis zur Zusage unbestätigt."},{id:"motivation-4-prepare-first",text:"Die heutigen fünf Minuten mit Betreuung zum Stimmen nutzen. Die Tonfolge für eine andere Übungszeit markieren.",feedback:"Stimmen und Markieren sind nützliche Vorbereitung, wenn sie nötig sind. Hier sind Instrument und Tonfolge bereit. Erneute Vorbereitung lässt das Üben ungetestet. Nutze die bestätigte Betreuung, um die Tonfolge tatsächlich zu spielen."}],bestOptionId:"motivation-4-confirmed-cover"}},carry:{takeaway:"Deine Lösung muss zum Hindernis passen. Schütze dabei echte Bedürfnisse und Verantwortlichkeiten.",followUp:{questionId:"motivation-4-barrier-response-return",question:"Hast du deine gespeicherte Handlung ausgeführt? Hat die geänderte Bedingung das beobachtete Hindernis angegangen?",observationPrompt:"Was war Übung, was Unterstützung, und welches Hindernis blieb bestehen?",adjustmentPrompt:"Welche einzelne Änderung hilft deinem nächsten Versuch im Alltag?"}},goDeeper:{sections:[{heading:"Planen kann helfen, der untersuchte Umfang zählt",paragraphs:["Wang und sein Team fassten 2021 in einem Überblick 21 Artikel und 24 Effekte zum mentalen Kontrastieren mit Wenn-dann-Plänen zusammen. Beim Erreichen von Zielen lag die durchschnittliche Wirkung im kleinen bis mittleren Bereich. Ergebnisse unterschieden sich nach Ziel. Es gab Hinweise auf Publikationsverzerrung. Ergebnis, Hindernis und Handlung zu verbinden garantiert nicht, dass Wünsche in Erfüllung gehen. Es zeigt weder, dass Gedanken äußere Ereignisse verändern, noch dass jedes WOOP-Format gleichwertig ist. [M10]","Duckworth und ihr Team prüften ein schulisches Programm mit 77 Kindern der fünften Klasse an einer Schule. Die Kinder arbeiteten in Kleingruppen an drei einstündigen Terminen. Dazu kamen wiederholte Übungen und Erinnerungskarten. Einige schulische Ergebnisse verbesserten sich. Spätere Gruppenunterschiede waren aber statistisch nicht signifikant. [M03] ODAs kurze Übung für Erwachsene verändert Teilnehmerkreis, Unterstützung und Dauer. Sie ist eine Anpassung zum Wählen einer prüfbaren Handlung, nicht das gesamte Programm. Probiere sie vorab, wenn das hilft. Trenne Vorbereitung vom echten Anlass, bei dem das Hindernis auftaucht und die Lösung gebraucht wird."]},{heading:"Das Hindernis angehen, ohne dich zu beschuldigen",paragraphs:["Die Planungsmethode betrachtet ein gewünschtes Ergebnis, ein Hindernis und eine gewählte Handlung dagegen. Sie belegt nicht, dass jedes Hindernis aus deiner Einstellung entsteht. Betreuung, Geld, fehlender Zugang bei Behinderung, Schichtarbeit, Krankheit und schädliches Verhalten anderer können begrenzen, was möglich ist. Eine praktische Lösung kann vereinbarte Hilfe, ein anderer Zeitplan, eine Anpassung, Erholung oder eine Grenze sein. Bei der Anwendung für Erwachsene müssen diese Umstände ehrlich benannt werden. [M03, M10]","Wähle anhand deiner tatsächlichen Notizen eine Bedingung, die du änderst. Kam das Startsignal ohne Materialien, löst ein größeres Versprechen das Problem nicht. Brauchte jemand deine Betreuung, muss diese Verantwortung abgesichert bleiben. Tauchte eine ablenkende Gewohnheit auf, teste eine Lösung, bei der dringender Kontakt weiter möglich ist. Ein nie aufgetretenes Hindernis lässt auch den Ersatzplan ungetestet. Halte den nützlichen Schritt getrennt vom Organisieren der Hilfe oder Bereitlegen der Materialien fest. Behalte später die Bedingungen, die funktioniert haben. Du musst keine neuen Rituale sammeln oder stärkere Motivation verlangen."]}],sourceIds:["M10","M03"]}},{schemaVersion:2,revision:2,id:"motivation-5",courseId:"motivation",locale:"de",title:"Tag ausgelassen? Finde eine Gelegenheit zum Wiedereinstieg.",goal:"Prüfe denselben Versuch. Behalte eine hilfreiche Bedingung und plane den nächsten machbaren Termin.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Mehrere Versuche ausgefallen? Hat sich dein Ziel geändert oder deine verfügbare Zeit?",reason:{id:"motivation-5-reason",label:"Ist dir dieses Ziel auch nächste Woche noch einen Platz im Alltag wert?",kind:"text",maxLength:160,optional:!0,suggestions:["Zu meinem weiterhin gewählten Ziel zurückkehren","Ein nicht mehr passendes Startsignal ändern","Erholung schützen und nötige Unterstützung suchen"]},why:{id:"motivation-5-why",label:"Ist dir dieses Ziel auch nächste Woche noch einen Platz im Alltag wert?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Prüfe deinen gewählten Grund, dein nützliches Minimum, das Startsignal und deine Notizen. Fortschritte zu verfolgen kann im Durchschnitt beim Erreichen von Zielen helfen. Ein ungetesteter Plan wird dadurch keine Handlung. Ein leeres Protokoll bedeutet kein Scheitern. Trenne Vorbereitung, tatsächliche Arbeit und Pause, wenn du beurteilst, was geholfen hat.","In einer Studie störte eine verpasste Gelegenheit die Gewohnheitsbildung nicht wesentlich. Damit ist nicht belegt, dass lange Unterbrechungen harmlos sind. Nutze passende Bedingungen erneut, ändere eine ungeeignete Gelegenheit oder überdenke dein Ziel. Gib dem nächsten nützlichen Schritt ein Datum. Du musst weder doppelt nachholen noch dir Erholung erst verdienen."],example:{title:"Leilas nächster Termin",text:"Am Sonntag prüft Leila denselben Plan für ihren Abschluss. Nach dem Abendessen klappte es zweimal. Eine geänderte Schicht verhinderte zwei weitere Versuche. Sie bleibt beim Ziel und legt eine Frage auf die verfügbare Mittagspause am Montag, mit zugänglichen Notizen. Sie schreibt die nächste Gelegenheit auf. Ausgefallene Versuche bleiben ausgefallen. Die Handlung am Montag ist weiterhin ein Plan."}},move:{invitation:"Prüfe deine Notizen. Wähle für denselben nützlichen Schritt ein Datum mit einer verfügbaren Gelegenheit.",instructions:["Ändere nur die Bedingung, die deine Versuche zeigen. Prüfe Datum und Umgebung.","Geplant sind nur dieser Versuch und der Rückblick am nächsten Tag. Wöchentlicher Rückblick bleibt freiwillig."],prompts:[],suggestions:{action:["Beispiel: meine gespeicherte Übungsfrage zum Abschluss beantworten","Meinen gespeicherten kurzen Spaziergang machen","Meinen vereinbarten Teil des Küchenputzens erledigen"],minimum:["Dieselbe Übungsfrage beantworten","Dieselbe sichere Fünf-Minuten-Strecke gehen","Dieselben beiden vereinbarten Tassen abwaschen"],cue:["Wenn meine bestätigte Mittagspause um 12:30 beginnt","Wenn meine feste Pause mittags beginnt","Nachdem unser gemeinsames Essen vorbei ist"],place:["An meinem für mich zugänglichen Pausentisch","Auf meinem zugänglichen Rundweg am Arbeitsplatz","An meiner für mich zugänglichen Küchenspüle"],minutes:[2,5],fallback:["Bei ausgefallener Mittagspause eine andere machbare Zeit festlegen","Bei unsicherer Strecke Bewegung im Sitzen wählen","Falls unmöglich, eine andere nützliche Putzaufgabe vereinbaren"],observation:["Konnte ich dieselbe Frage zur neuen Zeit beantworten","Tatsächliche Bewegung und verfügbare Zeit","Aufgabe erledigt und Umgebung passend"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],bundles:[{action:"Beispiel: meine gespeicherte Übungsfrage zum Abschluss beantworten",minimum:"Dieselbe Übungsfrage beantworten",cue:"Wenn meine bestätigte Mittagspause um 12:30 beginnt",place:"An meinem für mich zugänglichen Pausentisch",fallback:"Bei ausgefallener Mittagspause eine andere machbare Zeit festlegen",observation:"Konnte ich dieselbe Frage zur neuen Zeit beantworten",minutes:2},{action:"Meinen gespeicherten kurzen Spaziergang machen",minimum:"Dieselbe sichere Fünf-Minuten-Strecke gehen",cue:"Wenn meine feste Pause mittags beginnt",place:"Auf meinem zugänglichen Rundweg am Arbeitsplatz",fallback:"Bei unsicherer Strecke Bewegung im Sitzen wählen",observation:"Tatsächliche Bewegung und verfügbare Zeit",minutes:5},{action:"Meinen vereinbarten Teil des Küchenputzens erledigen",minimum:"Dieselben beiden vereinbarten Tassen abwaschen",cue:"Nachdem unser gemeinsames Essen vorbei ist",place:"An meiner für mich zugänglichen Küchenspüle",fallback:"Falls unmöglich, eine andere nützliche Putzaufgabe vereinbaren",observation:"Aufgabe erledigt und Umgebung passend",minutes:2}]},suggested:{action:"Beispiel: meine gespeicherte Übungsfrage zum Abschluss beantworten",minimum:"Dieselbe Übungsfrage beantworten",minutes:2,cueHint:"Wenn meine bestätigte Mittagspause um 12:30 beginnt",placeHint:"An meinem für mich zugänglichen Pausentisch",obstacleHint:"Beispiel: Meine dokumentierte Schichtänderung ließ keine Lernzeit am Abend",fallbackHint:"Bei ausgefallener Mittagspause eine andere machbare Zeit festlegen",observationHint:"Konnte ich dieselbe Frage zur neuen Zeit beantworten"},stopRule:"Bei anhaltendem Interessenverlust oder Schwierigkeiten im Alltag kannst du jetzt Unterstützung holen. Bei akuter Gefahr brauchst du sofort Hilfe.",accessibleAlternative:"Nutze zugängliche Materialien, vereinbarte Hilfe, eine Bitte um Unterstützung, Erholung oder eine ausdrückliche Pause."},result:{question:"Hast du deinen gewählten Wiedereinstieg tatsächlich umgesetzt?",observationPrompt:"Welche tatsächliche Handlung, Unterstützung oder Pause hast du festgehalten?"},judgment:{primary:{id:"motivation-5-recorded-barrier-decision",scenario:"Timos neue Schicht beginnt vor Ende des Abendessens. Die Zeit für seinen Abendspaziergang entfällt. Er möchte weiter spazieren gehen. Mittags ist täglich eine sichere Fünf-Minuten-Strecke verfügbar. Eine sichere Strecke vor der Schicht verlangt früheres Aufstehen; sonntags geht eine längere. Er möchte werktags wieder einsteigen, ohne weniger zu schlafen.",question:"Welcher Plan passt zum beobachteten Hindernis und Aufwand?",options:[{id:"motivation-5-early-walk",text:"Den Spaziergang vor die Schicht legen. Den Wecker früher stellen, um diese neue Zeit freizuhalten.",feedback:"Die Strecke vor der Schicht löst den Konflikt am Abend. Der frühere Wecker widerspricht aber seiner Grenze beim Schlaf. Die verfügbare Mittagspause lässt ihn den Wiedereinstieg werktags ohne diesen zusätzlichen Aufwand prüfen."},{id:"motivation-5-sunday-walk",text:"Zu einem längeren Sonntagsspaziergang wechseln. Prüfen, ob einmal pro Woche besser zu seinem Zeitplan passt.",feedback:"Ein wöchentlicher Spaziergang wäre eine machbare Zieländerung, kein Scheitern. Timo möchte gerade einen Versuch an Werktagen machen. Die Mittagspause ist verfügbar. Prüfe diese Bedingung, bevor er entscheidet, wie häufig er künftig gehen will."},{id:"motivation-5-lunch-return",text:"Die nächste Mittagspause festlegen, die sichere Fünf-Minuten-Strecke gehen und festhalten, ob die neue Zeit passt.",feedback:"So behält er Spaziergang und nützlichen Umfang bei und ändert die ungeeignete Abendzeit. Nur der tatsächliche Spaziergang zählt als Übung. Der morgige Rückblick kann helfen, diese Lösung zu wiederholen, zu ändern oder zu beenden."}],bestOptionId:"motivation-5-lunch-return"}},carry:{takeaway:"Behalte deinen Grund und die nützliche Handlung. Ändere die Bedingung, die laut deinen Notizen nicht funktioniert.",followUp:{questionId:"motivation-5-return",question:"Hat die neue Gelegenheit gepasst? Ist dir das Ziel den Aufwand auch nächste Woche noch wert?",observationPrompt:"Welche tatsächliche Handlung, Unterstützung oder Pause hast du festgehalten?",adjustmentPrompt:"Welche einzelne Änderung hilft deinem nächsten Versuch im Alltag?"}},goDeeper:{sections:[{heading:"Notizen auswerten, ohne eine Übungsserie zu erfinden",paragraphs:["Harkin und sein Team fanden im Überblick über 138 randomisierte Studien durchschnittliche Vorteile beim Erreichen von Zielen durch das Verfolgen von Fortschritten. Ziele und Methoden unterschieden sich. Aufschreiben und Berichten hingen als einzelne Merkmale mit größeren Effekten zusammen. Daraus folgt nicht, dass öffentliches Teilen oder ein wöchentlicher Rhythmus nötig sind. ODAs Rückblick am nächsten Tag ist eine Anpassung, kein belegter optimaler Umfang. Ein wöchentlicher Rückblick bleibt freiwillig. Dieser Plan legt ihn nicht automatisch fest. [M13]","Lallys Beobachtungsstudie fand, dass eine verpasste Gelegenheit ihren modellierten Verlauf der Gewohnheitsbildung nicht wesentlich störte. Dieses begrenzte Ergebnis beweist nicht, dass lange Unterbrechungen eine Gewohnheit unverändert lassen. [M05] Wähle anhand deiner eigenen Versuche, was folgt. Behalte einen nützlichen Schritt, ändere ein unpassendes Startsignal oder eine unpassende Lösung. Lass frühere Ausfälle sichtbar. Ein künftiger Plan bleibt geplant. Ist dir das Ziel seine Zeit nicht mehr wert, passe es bewusst an, verschiebe oder beende es. Lernen abzuschließen ist etwas anderes, als die Handlung auszuführen und später zu prüfen."]},{heading:"Freude bleibt freiwillig, Unterstützung ist jetzt möglich",paragraphs:["Die letzte Lektion führt denselben Versuch zusammen, statt ein neues Motivationsritual hinzuzufügen. Forschung zum Beobachten von Fortschritten unterstützt im Durchschnitt den Vergleich zwischen tatsächlichem Fortschritt und gewähltem Ziel. Sie zeigt nicht, welche Methode für jeden Menschen die beste ist. Deine Notizen können zeigen, ob eine Gelegenheit fehlte, Materialien nicht da waren oder der Zeitaufwand des Ziels nicht mehr passte. Wähle anhand dieser beobachteten Bedingung eine nächste Änderung. Zähle Vorbereitung oder ein Versprechen nicht als eigentliche Handlung. [M13]","Mach grundlegende Erholung oder sämtliche angenehmen Aktivitäten nicht von Produktivität abhängig. Wenn du später passende kostenlose Audioinhalte wählst, achte weiter auf Verkehr und Sicherheit. Anhaltender Interessenverlust, Belastung, Erschöpfung oder Schwierigkeiten mit üblichen Alltagsaufgaben können eine fachliche Abklärung brauchen. NIMH empfiehlt Unterstützung und sofortige Hilfe bei akuter Gefahr. Aus fehlender Motivation lässt sich damit keine Diagnose ableiten. Du musst nicht warten, bevor du Hilfe suchst. [M20] Während du dich darum kümmerst, kannst du einen kleinen nützlichen Schritt beibehalten, Unterstützung erbitten oder pausieren."]}],sourceIds:["M13","M05","M20"]}}];function t(e,r,h){const s=e.judgment.primary,n=[...s.options],u=n.findIndex(a=>a.id===s.bestOptionId);return[n[r],n[u]]=[n[u],n[r]],{id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,practice:[e.move.instructions[0],e.move.instructions[1],"Halte fest, was tatsächlich passiert ist. Schau morgen auf denselben Versuch zurück."],reflection:e.direction.reason.label,question:`${s.scenario} ${s.question}`,options:n.map(a=>a.text),correct:r,feedback:n[r].feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds,photo:h}}const l={id:"motivation",title:"Wartest du auf Motivation? Gib deinem Ziel heute Zeit.",subtitle:"Fünf Lektionen: Wähle ein Ziel, das dir den Aufwand wert ist. Teste ein nützliches Minimum und passe die Bedingungen an deine Woche an.",description:"Wähle, wofür du dich einsetzen willst. Probiere eine kleine, nützliche Handlung. Ändere Startsignal oder Unterstützung anhand dessen, was tatsächlich passiert ist.",scope:"Übungen für alltägliche Ziele. Anhaltende Antriebslosigkeit, Erschöpfung oder Schwierigkeiten im Alltag können mehr als ein Motivationsproblem sein. Unterstützung ist sinnvoll. Eine medizinische Fachperson kann dir helfen, die Ursache abzuklären.",outcome:"Eine gewählte Handlung und ein nächster Versuch mit Datum, passend zu deinen bisherigen Erfahrungen.",photo:{id:"1790004245013-b347139d5591",alt:"Ein Mann läuft auf einem sonnigen Waldweg"},lang:"de",lessons:[t(i[0],1,{id:"1517971129774-8a2b38fa128e",alt:"Eine Frau schreibt am Fenster in ein Notizbuch"}),t(i[1],2,{id:"1581578731509-8ae9c5a3e7d3",alt:"Ein Paar Schuhe neben der Tür"}),t(i[2],2,{id:"1499933374294-4584851497cc",alt:"Ein schwarzer Wecker auf einem Tisch"}),t(i[3],1,{id:"1575478004055-999ebe26dab7",alt:"Eine Frau geht mit einem Regenschirm durch den Regen"}),t(i[4],0,{id:"1577950248429-7530424d9682",alt:"Ein Monatskalender an einer Pinnwand"})]},g=Object.freeze(Object.defineProperty({__proto__:null,COURSE:l,LESSONS_V2:i,SOURCES:d},Symbol.toStringTag,{value:"Module"}));export{g as m};
